deepml motion 0.3
module corpus.deepml_motion.example_04501
policy deterministic
policy no_network
skeleton Rig04501 { joint Root parent none joint Hip parent Root joint FootL parent Hip joint FootR parent Hip }
procedural animation Procedural04501 seed 4501 {
  trajectory = predict_trajectory(velocity, horizon=1.0s)
  match = motion_match(database="local:motions_1", trajectory=trajectory)
  constrain contact FootL to ground when phase < 0.5
  constrain contact FootR to ground when phase >= 0.5
}
layered state_machine Layers04501 { base: Locomotion upper: Gesture additive: Breathing }
synchronize Procedural04501 with scene.Actor13 and timeline.Sequence3

